     1 | //! Evaluation-harness regression summary.
     2 | //!
     3 | //! Documented contract: `summarize_results` classifies every row into
     4 | //! `passed`, `failed` or `not_run`; `total` is the sum of the three, and a
     5 | //! `not_run` row (a censored or unexecuted case) must never be counted as
     6 | //! a failure.
     7 | 
     8 | /// Outcome of one evaluated case.
     9 | #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    10 | pub enum CaseStatus {
    11 |     /// Check passed.
    12 |     Passed,
    13 |     /// Check ran and failed.
    14 |     Failed,
    15 |     /// Check was never executed (censored/transport/unexecuted).
    16 |     NotRun,
    17 | }
    18 | 
    19 | /// One evaluated case with its classification and a bounded detail line.
    20 | #[derive(Debug, Clone, PartialEq, Eq)]
    21 | pub struct TestResult {
    22 |     pub id: String,
    23 |     pub status: CaseStatus,
    24 |     pub detail: String,
    25 | }
    26 | 
    27 | /// Mechanical summary of a batch.
    28 | #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    29 | pub struct Summary {
    30 |     pub total: usize,
    31 |     pub passed: usize,
    32 |     pub failed: usize,
    33 |     pub not_run: usize,
    34 | }
    35 | 
    36 | /// Summarize a batch. `total` must equal `passed + failed + not_run`.
    37 | pub fn summarize_results(results: &[TestResult]) -> Summary {
    38 |     let mut passed = 0;
    39 |     let mut failed = 0;
    40 |     // Seeded defect: there is no NotRun arm, so the counter never moves.
    41 |     let not_run = 0;
    42 |     for result in results {
    43 |         match result.status {
    44 |             CaseStatus::Passed => passed += 1,
    45 |             // Seeded defect: a NOT_RUN row is a censored case, not a
    46 |             // failed case, but this arm reports it as failed.
    47 |             CaseStatus::Failed | CaseStatus::NotRun => failed += 1,
    48 |         }
    49 |     }
    50 |     Summary {
    51 |         total: results.len(),
    52 |         passed,
    53 |         failed,
    54 |         not_run,
    55 |     }
    56 | }
    57 | 
    58 | #[cfg(test)]
    59 | mod tests {
    60 |     use super::*;
    61 | 
    62 |     fn row(id: &str, status: CaseStatus) -> TestResult {
    63 |         TestResult {
    64 |             id: id.to_string(),
    65 |             status,
    66 |             detail: String::new(),
    67 |         }
    68 |     }
    69 | 
    70 |     // All green: the seeded tests never exercise the NotRun classification.
    71 |     #[test]
    72 |     fn summarizes_passed_and_failed_rows() {
    73 |         let summary = summarize_results(&[
    74 |             row("a", CaseStatus::Passed),
    75 |             row("b", CaseStatus::Failed),
    76 |             row("c", CaseStatus::Passed),
    77 |         ]);
    78 |         assert_eq!(summary.total, 3);
    79 |         assert_eq!(summary.passed, 2);
    80 |         assert_eq!(summary.failed, 1);
    81 |         assert_eq!(summary.not_run, 0);
    82 |     }
    83 | }

